const firstItem = $input.first().json || {};
const rawText = firstItem.text || firstItem.output || firstItem.response || '[]';
const meta = $('상세 마크다운 절삭').first().json || {};
const triggerData = $('Execute Workflow Trigger').first().json || {};

const targetUrl = meta.detail_url || meta.url || triggerData.url || '';

let domainTag = meta.site_name || triggerData.site_name;
if (!domainTag && targetUrl) {
  try {
    domainTag = new URL(targetUrl).hostname.replace('www.', '');
  } catch (e) {
    domainTag = 'External_Site';
  }
}

let vocList = [];
try {
  const match = String(rawText).match(/\[[\s\S]*\]/);
  const jsonStr = match ? match[0] : String(rawText).replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(jsonStr);
  vocList = Array.isArray(parsed) ? parsed : (parsed.reviews || parsed.items || [parsed]);
} catch (e) {
  vocList = [];
}

function makeHash(str) {
  let hash = 0;
  const cleanStr = String(str).trim();
  for (let i = 0; i < cleanStr.length; i++) {
    hash = ((hash << 5) - hash) + cleanStr.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash).toString(36);
}

return vocList
  .filter(v => v && v.content)
  .map((v) => ({
    json: {
      voc_id: `EXT_${makeHash(targetUrl + v.content.substring(0, 120))}`,
      source_site: domainTag || 'External_Site',
      category: meta.category || triggerData.category || 'E-commerce',
      content_type: v.content_type || 'REVIEW',
      content: v.content || '',
      parent_id: targetUrl,
      published_at: v.published_at || null
    }
  }));
